// Regenerates lib/src/rules/school_holidays_data.dart from the OpenHolidays
// API (https://www.openholidaysapi.org, data under the ODbL). Usage (from
// packages/core):
//   dart run tool/fetch_school_holidays.dart [firstYear] [lastYear]
// Defaults: last year to five years ahead. Run it when a state publishes new
// dates; the generated file is committed (calculations.md §10.5).
import 'dart:convert';
import 'dart:io';

import 'package:http/http.dart' as http;
import 'package:timetrack_core/timetrack_core.dart';

const _out = 'lib/src/rules/school_holidays_data.dart';

/// Fetches the school holidays of every state and writes the data file.
Future<void> main(List<String> args) async {
  final now = DateTime.now().year;
  final first = args.isNotEmpty ? int.parse(args[0]) : now - 1;
  final last = args.length > 1 ? int.parse(args[1]) : now + 5;
  final byState = {for (final s in FederalState.values) s: <String>{}};
  // The API answers at most three years per request.
  for (var from = first; from <= last; from += 3) {
    final to = from + 2 > last ? last : from + 2;
    final uri = Uri.https('openholidaysapi.org', '/SchoolHolidays', {
      'countryIsoCode': 'DE',
      'languageIsoCode': 'DE',
      'validFrom': '$from-01-01',
      'validTo': '$to-12-31',
    });
    final response = await http.get(
      uri,
      headers: {'accept': 'application/json'},
    );
    if (response.statusCode != 200) {
      stderr.writeln('$uri: HTTP ${response.statusCode}');
      exit(1);
    }
    final holidays = (jsonDecode(utf8.decode(response.bodyBytes)) as List)
        .cast<Map<String, Object?>>();
    for (final h in holidays) {
      List<Map<String, Object?>> list(String key) =>
          ((h[key] as List?) ?? const []).cast<Map<String, Object?>>();
      final groups = [for (final g in list('groups')) g['code'] as String];
      // Some states (MV) list vocational schools separately: keep the
      // general schools' dates. Exceptions are a few regions only (the SH
      // islands).
      if (groups.isNotEmpty && !groups.any((g) => g.endsWith('-ABS')) ||
          ((h['tags'] as List?) ?? const []).contains('Exception')) {
        continue;
      }
      final name = list('name').first['text'] as String;
      for (final s in list('subdivisions')) {
        final code = (s['code'] as String).split('-').last;
        byState[FederalState.parse(code)]!.add(
          '${h['startDate']} ${h['endDate']} $name',
        );
      }
    }
  }
  final out = StringBuffer()
    ..writeln('// GENERATED by tool/fetch_school_holidays.dart. Do not edit.')
    ..writeln('//')
    ..writeln('// School holidays of the German states, $first–$last.')
    ..writeln('// Source: OpenHolidays API (https://www.openholidaysapi.org).')
    ..writeln('// This data is made available under the Open Database License')
    ..writeln('// (ODbL 1.0, https://opendatacommons.org/licenses/odbl/1-0/).')
    ..writeln()
    ..writeln("import 'holidays.dart';")
    ..writeln()
    ..writeln('/// Per state: `start end name`, dates inclusive (ISO 8601).')
    ..writeln('const schoolHolidayData = <FederalState, List<String>>{');
  for (final MapEntry(key: state, value: lines) in byState.entries) {
    out.writeln('  FederalState.${state.name}: [');
    for (final line in lines.toList()..sort()) {
      out.writeln("    '${line.replaceAll("'", r"\'")}',");
    }
    out.writeln('  ],');
  }
  out.writeln('};');
  File(_out).writeAsStringSync(out.toString());
  stdout.writeln('Wrote $_out');
}
